<template><div><div class="page-title"><div><p class="eyebrow">SERVICE</p><h1>订单管理</h1><p>每 5 秒自动刷新 · <el-tag type="danger">🔔 新订单 {{newCount}}</el-tag></p></div></div><el-alert v-if="error" :title="error" type="error" :closable="false"/><el-table :data="orders" stripe><el-table-column prop="id" label="订单编号" min-width="190"/><el-table-column prop="tableNo" label="桌号" width="80"/><el-table-column label="菜品" min-width="200"><template #default="s">{{s.row.items.map((i:any)=>`${i.name} × ${i.quantity}`).join('、')}}</template></el-table-column><el-table-column label="金额" width="120"><template #default="s">¥{{s.row.total.toLocaleString()}}</template></el-table-column><el-table-column label="下单时间" min-width="170"><template #default="s">{{new Date(s.row.createdAt).toLocaleString()}}</template></el-table-column><el-table-column label="状态" width="145"><template #default="s"><el-select :model-value="s.row.status" @change="(v:string)=>change(s.row,v)"><el-option v-for="o in states" :key="o.value" :label="o.label" :value="o.value"/></el-select></template></el-table-column></el-table></div></template><script setup lang="ts">import {ref,computed,onMounted,onUnmounted} from 'vue';import {api} from '../api';import {activeStoreId} from '../storeContext';const orders=ref<any[]>([]),error=ref(''),newCount=computed(()=>orders.value.filter(o=>o.status==='new').length),states=[{value:'new',label:'新订单'},{value:'preparing',label:'制作中'},{value:'completed',label:'已完成'},{value:'cancelled',label:'已取消'}];async function load(){try{orders.value=(await api.get('/orders',{params:{storeId:activeStoreId.value}})).data.data;error.value=''}catch(e:any){error.value=e.message}}async function change(o:any,status:string){try{await api.patch(`/orders/${o.id}/status`,{status});await load()}catch(e:any){error.value=e.message}}let timer:number;onMounted(()=>{load();timer=window.setInterval(load,5000)});import {watch} from 'vue';watch(activeStoreId,load);onUnmounted(()=>clearInterval(timer));</script>

